    conn: sqlite3.Connection,
    contract_code: str,
    milestone_code: str,
    invoice_code: str,
    amount_text: str,
    date_text: str,
) -> str:
    contract_code = require_text(contract_code, "合同编号")
    milestone_code = require_text(milestone_code, "里程碑编号")
    invoice_code = require_text(invoice_code, "发票编号")
